-- flagged = cadasters with in-scope post2020 loss
CREATE OR REPLACE TABLE flagged AS
SELECT m.cod_imovel, sum(m.post2020_ha) FILTER(WHERE c.in_scope) AS inscope_post2020
FROM matched m JOIN class_scope c ON CAST(m.mbmode24 AS INTEGER)=c.mbmode24
GROUP BY 1 HAVING sum(m.post2020_ha) FILTER(WHERE c.in_scope) > 0;
SELECT count(*) n_flagged FROM flagged;
-- dominant class per cadaster (hectares, tie lower code)
CREATE OR REPLACE TABLE dom AS
WITH ch AS (
  SELECT cod_imovel, CAST(mbmode24 AS INTEGER) mb, sum(field_ha) ha
  FROM matched GROUP BY 1,2)
SELECT cod_imovel, arg_max(mb, (ha, -mb)) AS dominant_mb
FROM ch GROUP BY 1;
SELECT d.dominant_mb, count(*) FROM flagged f JOIN dom d USING(cod_imovel) GROUP BY 1 ORDER BY 1;
"

