      FROM fmeta ORDER BY cod_imovel) TO '/workspace/answers/q24.csv' (HEADER, DELIMITER ',');

-- Q25 in-scope commodities present with delivery tier coverage
COPY (
  SELECT annex1_commodity, tier, coverage FROM (
    SELECT 'cattle' annex1_commodity, 'slaughter_point' tier, 'covered' coverage
    UNION ALL SELECT 'soya','intake_point','covered'
  ) ORDER BY annex1_commodity
) TO '/workspace/answers/q25.csv' (HEADER, DELIMITER ',');

