  SELECT cod_imovel,
    (arg_min(entity_id,(dist_km,entity_id))) AS entity_id,
    (arg_min(tier,(dist_km,entity_id))) AS tier,
    min(dist_km) AS distance_km
  FROM delcand GROUP BY cod_imovel ORDER BY cod_imovel
) TO '/workspace/answers/q26.csv' (HEADER, DELIMITER ',');

