COPY (
  SELECT f.cod_imovel, m.muni AS entity_id, m.evidence
  FROM fmeta f JOIN memb m ON m.muni=f.muni ORDER BY f.cod_imovel
) TO '/workspace/answers/q27.csv' (HEADER, DELIMITER ',');
